package com.zajel.app.data;
import com.zajel.app.core.SupabaseClient;import com.zajel.app.domain.*;import java.util.*;import java.util.concurrent.Executors;import org.json.*;
public final class SupabaseChatRepository implements ChatRepository {
 private final SupabaseClient api; private final SecureSessionStore sessions;
 public SupabaseChatRepository(SupabaseClient a,SecureSessionStore s){api=a;sessions=s;}
 public void conversations(Callback<List<Conversation>> cb){Executors.newSingleThreadExecutor().execute(()->{try{UserSession u=required();String path="/rest/v1/conversation_members?user_id=eq."+u.userId+"&select=conversation_id,conversations(id,title,is_direct)&order=created_at.desc";JSONObject r=api.request("GET",path,u.accessToken,null);JSONArray rows=r.optJSONArray("rows");List<Conversation> out=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);JSONObject c=row==null?null:row.optJSONObject("conversations");if(c!=null)out.add(new Conversation(c.optString("id"),c.optString("title"),c.optBoolean("is_direct")));}cb.success(out);}catch(Exception e){cb.error(e);}});}
 public void messages(String id,Callback<List<Message>> cb){Executors.newSingleThreadExecutor().execute(()->{try{UserSession u=required();String path="/rest/v1/messages?conversation_id=eq."+id+"&select=id,conversation_id,sender_id,body,created_at&order=created_at.asc&limit=100";JSONObject r=api.request("GET",path,u.accessToken,null);JSONArray rows=r.optJSONArray("rows");List<Message> out=new ArrayList<>();if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject x=rows.optJSONObject(i);if(x!=null)out.add(message(x));}cb.success(out);}catch(Exception e){cb.error(e);}});}
 public void sendText(String id,String body,Callback<Message> cb){Executors.newSingleThreadExecutor().execute(()->{try{UserSession u=required();JSONObject payload=new JSONObject().put("conversation_id",id).put("sender_id",u.userId).put("body",body).put("message_type","text");JSONObject r=api.request("POST","/rest/v1/messages",u.accessToken,payload);JSONArray rows=r.optJSONArray("rows");JSONObject x=rows==null?null:rows.optJSONObject(0);if(x==null)throw new IllegalStateException("Message was not acknowledged");cb.success(message(x));}catch(Exception e){cb.error(e);}});}
 private Message message(JSONObject x){return new Message(x.optString("id"),x.optString("conversation_id"),x.optString("sender_id"),x.optString("body"),x.optString("created_at"));}
 private UserSession required(){UserSession u=sessions.read();if(u==null)throw new IllegalStateException("Not signed in");return u;}
}
